"""Strict grain completeness and the legacy diagnostic score.

No aggregate score may override a failing required grain.
"""

from __future__ import annotations

from dataclasses import dataclass

from kakeyalogic.grains import Grain, GrainBundle, Outcome, SAVER
from kakeyalogic.state import FieldState, TypedObject


@dataclass(frozen=True)
class CompletenessReport:
    status: str
    kcomplete: bool
    missing: tuple[dict, ...]
    diagnostic_score: float | None
    note: str

    def to_dict(self) -> dict:
        return {
            "status": self.status,
            "kcomplete": self.kcomplete,
            "missing": list(self.missing),
            "diagnostic_score": self.diagnostic_score,
            "note": self.note,
        }


def kcomplete(
    bundle: GrainBundle,
    direction_ids: tuple[str, ...],
    grains: tuple[Grain, ...] = SAVER,
    *,
    weights: dict[str, float] | None = None,
    required_grains_by_direction: dict[str, tuple[Grain, ...]] | None = None,
) -> CompletenessReport:
    requirements = {
        d: (required_grains_by_direction or {}).get(d, grains)
        for d in direction_ids
    }
    direction_ids = tuple(d for d in direction_ids if requirements[d])
    if not direction_ids:
        return CompletenessReport(
            status="NOT_APPLICABLE",
            kcomplete=False,
            missing=(),
            diagnostic_score=None,
            note="empty required-grain field is NOT APPLICABLE, not a perfect result",
        )
    missing: list[dict] = []
    passed_dirs = 0
    for direction_id in direction_ids:
        dir_ok = True
        for grain in requirements[direction_id]:
            cell = bundle.cell(direction_id, grain)
            outcome = cell.outcome if cell else Outcome.NOT_EVALUATED
            if outcome is not Outcome.PASS:
                dir_ok = False
                missing.append(
                    {
                        "direction_id": direction_id,
                        "grain": grain.value,
                        "outcome": outcome.value,
                    }
                )
        if dir_ok:
            passed_dirs += 1
    score = None
    if weights is None:
        score = passed_dirs / len(direction_ids)
    else:
        num = sum(weights.get(d, 1.0) for d in direction_ids if not any(
            m["direction_id"] == d for m in missing
        ))
        den = sum(weights.get(d, 1.0) for d in direction_ids)
        score = num / den if den else None
    complete = not missing
    return CompletenessReport(
        status="PASS" if complete else "FAIL",
        kcomplete=complete,
        missing=tuple(missing),
        diagnostic_score=score,
        note=(
            "diagnostic_score is a legacy per-direction summary; it does not "
            "override a failing required grain"
        ),
    )


def retention_bundle_from_objects(
    state: FieldState,
    *,
    prior_objects: dict[str, TypedObject] | None = None,
) -> GrainBundle:
    """Re-evaluate Retention after a later update.

    A required held correction, red line, or evidence object that is no longer
    recoverable fails Retention. Prior failed/unresolved edges are not scored
    here; they are retained separately in the ledger.
    """
    from kakeyalogic.grains import GrainCell

    cells = []
    prior = prior_objects or {}
    for direction in state.directions.values():
        required_objs = [
            obj
            for obj in prior.values()
            if obj.direction_id == direction.direction_id and obj.held
        ]
        lost = [
            obj
            for obj in required_objs
            if obj.object_id not in state.objects
            or not state.objects[obj.object_id].recoverable
        ]
        if lost and any(obj.role in {"correction", "red_line", "evidence"} or obj.type in {"correction", "red_line"} for obj in lost):
            outcome = Outcome.FAIL
            reason = (
                "required correction/red-line/evidence is no longer recoverable: "
                + ", ".join(o.object_id for o in lost)
            )
        elif lost:
            outcome = Outcome.FAIL
            reason = "required held object is no longer recoverable: " + ", ".join(
                o.object_id for o in lost
            )
        elif not any(
            obj.direction_id == direction.direction_id and obj.held and obj.recoverable
            for obj in state.objects.values()
        ):
            outcome = Outcome.UNRESOLVED
            reason = "no recoverable held object remains for this direction"
        else:
            outcome = Outcome.PASS
            reason = "required held objects remain recoverable"
        cells.append(
            GrainCell(
                direction_id=direction.direction_id,
                grain=Grain.R,
                outcome=outcome,
                check="longitudinal_retention",
                reason=reason,
                evidence_refs=tuple(
                    o.object_id
                    for o in state.objects.values()
                    if o.direction_id == direction.direction_id
                ),
            )
        )
    from kakeyalogic.grains import GrainBundle as Bundle

    return Bundle(cells=tuple(cells))

"""Partition candidate transitions into admitted, unresolved, and failed sets."""

from __future__ import annotations

from dataclasses import dataclass

from kakeyalogic.grains import (
    GatePartition,
    GrainBundle,
    TransitionClass,
    classify_outcomes,
    refuse_weighted_override,
)
from kakeyalogic.interior import InteriorReport, evaluate_interior
from kakeyalogic.state import CandidateEdge


@dataclass(frozen=True)
class EvaluatedEdge:
    edge: CandidateEdge
    bundle: GrainBundle
    classification: TransitionClass
    interior: InteriorReport
    admission_issues: tuple[str, ...] = ()

    @property
    def edge_id(self) -> str:
        return self.edge.edge_id

    def to_dict(self) -> dict:
        return {
            "edge_id": self.edge.edge_id,
            "src": self.edge.src,
            "dst": self.edge.dst,
            "cost": self.edge.cost,
            "classification": self.classification.value,
            "bundle": self.bundle.to_dict(),
            "interior": self.interior.to_dict(),
            "boundary_error": self.interior.boundary_error,
            "admission_issues": list(self.admission_issues),
        }


def evaluate_edge(edge: CandidateEdge) -> EvaluatedEdge:
    interior = evaluate_interior(edge)
    classification = classify_outcomes(interior.bundle.outcomes_for(edge.required_pairs()))
    return EvaluatedEdge(
        edge=edge,
        bundle=interior.bundle,
        classification=classification,
        interior=interior,
    )


def grain_and_gate(
    edges: dict[str, CandidateEdge],
    *,
    weights: dict[str, float] | None = None,
) -> tuple[dict[str, EvaluatedEdge], GatePartition]:
    refuse_weighted_override(weights)
    evaluated = {edge_id: evaluate_edge(edge) for edge_id, edge in edges.items()}
    return evaluated, partition_evaluated(evaluated)


def partition_evaluated(evaluated: dict[str, EvaluatedEdge]) -> GatePartition:
    """Build the routing sets from the final, including overlap, evaluation."""
    admitted: list[str] = []
    unresolved: list[str] = []
    failed: list[str] = []
    not_applicable: list[str] = []
    by_id: dict[str, TransitionClass] = {}
    for edge_id, item in sorted(evaluated.items()):
        by_id[edge_id] = item.classification
        if item.classification is TransitionClass.ADMITTED:
            admitted.append(edge_id)
        elif item.classification is TransitionClass.UNRESOLVED:
            unresolved.append(edge_id)
        elif item.classification is TransitionClass.FAILED:
            failed.append(edge_id)
        else:
            not_applicable.append(edge_id)
    partition = GatePartition(
        admitted=tuple(admitted),
        unresolved=tuple(unresolved),
        failed=tuple(failed),
        not_applicable=tuple(not_applicable),
        by_id=by_id,
    )
    return partition

"""Geodecis: operational route selection on KakeyaLogic-admitted transitions.

The cost is explicitly operational. It is not a safety, ethics, truth, or
Love-Squared Coherence score. KakeyaLogic determines admissibility; Geodecis
chooses among admitted continuations.
"""

from __future__ import annotations

from dataclasses import dataclass
from heapq import heappop, heappush
from math import inf

from kakeyalogic.gate import EvaluatedEdge
from kakeyalogic.grains import TransitionClass


@dataclass(frozen=True)
class Path:
    nodes: tuple[str, ...]
    edge_ids: tuple[str, ...]
    cost: float

    def to_dict(self) -> dict:
        return {
            "nodes": list(self.nodes),
            "edge_ids": list(self.edge_ids),
            "cost": None if self.cost == inf else self.cost,
        }


@dataclass(frozen=True)
class DistanceReport:
    source: str
    goal: str
    admitted: Path
    diamond: Path
    evidence_sensitivity: float | None
    next_step: str | None
    next_edge_id: str | None

    def to_dict(self) -> dict:
        return {
            "source": self.source,
            "goal": self.goal,
            "admitted": self.admitted.to_dict(),
            "diamond": self.diamond.to_dict(),
            "evidence_sensitivity": self.evidence_sensitivity,
            "next_step": self.next_step,
            "next_edge_id": self.next_edge_id,
            "note": (
                "evidence_sensitivity is a diagnostic, not permission to traverse "
                "unresolved edges"
            ),
        }


def _usable(item: EvaluatedEdge, *, include_unresolved: bool) -> bool:
    if item.classification is TransitionClass.ADMITTED:
        return True
    if include_unresolved and item.classification is TransitionClass.UNRESOLVED:
        return True
    return False


def shortest_path(
    evaluated: dict[str, EvaluatedEdge],
    source: str,
    goal: str,
    *,
    include_unresolved: bool = False,
) -> Path:
    """Directed Dijkstra on positive operational costs. No symmetry assumed."""
    if source == goal:
        return Path(nodes=(source,), edge_ids=(), cost=0.0)

    adj: dict[str, list[tuple[float, str, str]]] = {}
    for item in evaluated.values():
        if not _usable(item, include_unresolved=include_unresolved):
            continue
        adj.setdefault(item.edge.src, []).append(
            (item.edge.cost, item.edge.dst, item.edge.edge_id)
        )

    dist: dict[str, float] = {source: 0.0}
    prev: dict[str, tuple[str, str]] = {}
    heap: list[tuple[float, str]] = [(0.0, source)]
    seen: set[str] = set()

    while heap:
        cost, node = heappop(heap)
        if node in seen:
            continue
        seen.add(node)
        if node == goal:
            break
        for edge_cost, dst, edge_id in adj.get(node, []):
            cand = cost + edge_cost
            if cand < dist.get(dst, inf):
                dist[dst] = cand
                prev[dst] = (node, edge_id)
                heappush(heap, (cand, dst))

    if goal not in dist:
        return Path(nodes=(), edge_ids=(), cost=inf)

    nodes = [goal]
    edge_ids: list[str] = []
    cursor = goal
    while cursor != source:
        parent, edge_id = prev[cursor]
        edge_ids.append(edge_id)
        nodes.append(parent)
        cursor = parent
    nodes.reverse()
    edge_ids.reverse()
    return Path(nodes=tuple(nodes), edge_ids=tuple(edge_ids), cost=dist[goal])


def admitted_distance(evaluated: dict[str, EvaluatedEdge], source: str, goal: str) -> Path:
    return shortest_path(evaluated, source, goal, include_unresolved=False)


def diamond_distance(evaluated: dict[str, EvaluatedEdge], source: str, goal: str) -> Path:
    """Distance on E^A ∪ E^U. Diagnostic only; unresolved edges are not traversable."""
    return shortest_path(evaluated, source, goal, include_unresolved=True)


def evidence_sensitivity(admitted: Path, diamond: Path) -> float | None:
    if admitted.cost is inf or diamond.cost is inf:
        return None
    delta = admitted.cost - diamond.cost
    if delta < 0:
        # Numerical guard: diamond is a relaxation of admitted, so delta >= 0.
        return 0.0
    return delta


def next_step(
    evaluated: dict[str, EvaluatedEdge],
    source: str,
    goal: str,
) -> tuple[str | None, str | None]:
    """Geodecis one-step policy: argmin_y [ℓ(x,y) + d^A(y,g)] over admitted edges."""
    outgoing = [
        item
        for item in evaluated.values()
        if item.edge.src == source and item.classification is TransitionClass.ADMITTED
    ]
    if not outgoing:
        return None, None
    best: tuple[float, str, str] | None = None
    for item in outgoing:
        rest = admitted_distance(evaluated, item.edge.dst, goal)
        if rest.cost is inf:
            continue
        total = item.edge.cost + rest.cost
        candidate = (total, item.edge.dst, item.edge.edge_id)
        if best is None or candidate < best:
            best = candidate
    if best is None:
        return None, None
    return best[1], best[2]


def geodecis_report(
    evaluated: dict[str, EvaluatedEdge],
    source: str,
    goal: str,
) -> DistanceReport:
    admitted = admitted_distance(evaluated, source, goal)
    diamond = diamond_distance(evaluated, source, goal)
    nxt, nxt_edge = next_step(evaluated, source, goal)
    return DistanceReport(
        source=source,
        goal=goal,
        admitted=admitted,
        diamond=diamond,
        evidence_sensitivity=evidence_sensitivity(admitted, diamond),
        next_step=nxt,
        next_edge_id=nxt_edge,
    )

"""SAVER grain field, outcomes, and the non-compensatory admission gate.

Grains are preservation dimensions, not interchangeable weights and not a
scalar safety score. A strong grain cannot compensate for a failed required
grain.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Iterable, Mapping, Sequence


class Grain(str, Enum):
    """The five KakeyaLogic grains: Semantic, Authority, Visibility, Enforceability, Retention."""

    S = "S"
    A = "A"
    V = "V"
    E = "E"
    R = "R"

    @property
    def label(self) -> str:
        return {
            Grain.S: "Semantic",
            Grain.A: "Authority",
            Grain.V: "Visibility",
            Grain.E: "Enforceability",
            Grain.R: "Retention",
        }[self]


SAVER: tuple[Grain, ...] = (Grain.S, Grain.A, Grain.V, Grain.E, Grain.R)


class Outcome(str, Enum):
    PASS = "PASS"
    UNRESOLVED = "UNRESOLVED"
    FAIL = "FAIL"
    NOT_EVALUATED = "NOT_EVALUATED"


class TransitionClass(str, Enum):
    ADMITTED = "ADMITTED"
    UNRESOLVED = "UNRESOLVED"
    FAILED = "FAILED"
    NOT_APPLICABLE = "NOT_APPLICABLE"


GRAIN_LABELS = {g.value: g.label for g in SAVER}


def parse_grain(value: str) -> Grain:
    try:
        return Grain(value)
    except ValueError as exc:
        raise ValueError(f"unknown grain {value!r}; expected one of {[g.value for g in SAVER]}") from exc


def parse_outcome(value: str) -> Outcome:
    try:
        return Outcome(value)
    except ValueError as exc:
        raise ValueError(f"unknown outcome {value!r}") from exc


@dataclass(frozen=True)
class GrainCell:
    """One evaluated cell of the finite field D_required × G."""

    direction_id: str
    grain: Grain
    outcome: Outcome
    check: str
    reason: str
    evidence_refs: tuple[str, ...] = ()

    def to_dict(self) -> dict:
        return {
            "direction_id": self.direction_id,
            "grain": self.grain.value,
            "grain_label": self.grain.label,
            "outcome": self.outcome.value,
            "check": self.check,
            "reason": self.reason,
            "evidence_refs": list(self.evidence_refs),
        }


def _cell_key(direction_id: str, grain: Grain) -> tuple[str, Grain]:
    return (direction_id, grain)


@dataclass(frozen=True)
class GrainBundle:
    """Inspectable grain state for one or more required directions.

    Cells are keyed by (direction_id, grain) so overlapping representation
    cannot silently merge independently recoverable grain state.
    """

    cells: tuple[GrainCell, ...] = ()

    def index(self) -> dict[tuple[str, Grain], GrainCell]:
        return {_cell_key(c.direction_id, c.grain): c for c in self.cells}

    def cell(self, direction_id: str, grain: Grain) -> GrainCell | None:
        return self.index().get(_cell_key(direction_id, grain))

    def outcomes_for(self, required: Sequence[tuple[str, Grain]]) -> list[Outcome]:
        idx = self.index()
        out: list[Outcome] = []
        for direction_id, grain in required:
            cell = idx.get(_cell_key(direction_id, grain))
            out.append(cell.outcome if cell is not None else Outcome.NOT_EVALUATED)
        return out

    def replace(self, updated: GrainCell) -> "GrainBundle":
        idx = self.index()
        idx[_cell_key(updated.direction_id, updated.grain)] = updated
        ordered = tuple(idx[k] for k in sorted(idx, key=lambda t: (t[0], t[1].value)))
        return GrainBundle(cells=ordered)

    def to_dict(self) -> list[dict]:
        return [c.to_dict() for c in self.cells]


def required_pairs(
    direction_ids: Sequence[str],
    grains: Sequence[Grain],
) -> tuple[tuple[str, Grain], ...]:
    return tuple((d, q) for d in direction_ids for q in grains)


def classify_outcomes(outcomes: Iterable[Outcome]) -> TransitionClass:
    """Non-compensatory gate.

    PASS only when every required outcome is PASS.
    FAIL if any required outcome is FAIL.
    UNRESOLVED if no FAIL and at least one UNRESOLVED or NOT_EVALUATED.
    NOT_APPLICABLE if the required set is empty.
    """
    seq = list(outcomes)
    if not seq:
        return TransitionClass.NOT_APPLICABLE
    if any(o is Outcome.FAIL for o in seq):
        return TransitionClass.FAILED
    if any(o in (Outcome.UNRESOLVED, Outcome.NOT_EVALUATED) for o in seq):
        return TransitionClass.UNRESOLVED
    if all(o is Outcome.PASS for o in seq):
        return TransitionClass.ADMITTED
    return TransitionClass.UNRESOLVED


def combine_outcomes(outcomes: Sequence[Outcome]) -> Outcome:
    """Combine several observations of the same grain without collapsing
    NOT_EVALUATED into UNRESOLVED.
    """
    if not outcomes:
        return Outcome.NOT_EVALUATED
    if any(o is Outcome.FAIL for o in outcomes):
        return Outcome.FAIL
    if any(o is Outcome.NOT_EVALUATED for o in outcomes):
        return Outcome.NOT_EVALUATED
    if any(o is Outcome.UNRESOLVED for o in outcomes):
        return Outcome.UNRESOLVED
    return Outcome.PASS


def refuse_weighted_override(weights: Mapping[str, float] | None = None) -> None:
    """Admission is a conjunction, never a weighted sum."""
    if weights:
        raise ValueError(
            "grain weights cannot override the admission gate; "
            "a strong grain cannot compensate for a failed required grain"
        )


@dataclass
class GatePartition:
    admitted: tuple[str, ...] = ()
    unresolved: tuple[str, ...] = ()
    failed: tuple[str, ...] = ()
    not_applicable: tuple[str, ...] = ()
    by_id: dict[str, TransitionClass] = field(default_factory=dict)

    def class_of(self, edge_id: str) -> TransitionClass | None:
        return self.by_id.get(edge_id)

    def to_dict(self) -> dict:
        return {
            "admitted": list(self.admitted),
            "unresolved": list(self.unresolved),
            "failed": list(self.failed),
            "not_applicable": list(self.not_applicable),
        }

"""Overlap: shared representation without merging direction identity or grain state."""

from __future__ import annotations

from dataclasses import dataclass, replace

from kakeyalogic.gate import EvaluatedEdge
from kakeyalogic.grains import SAVER, TransitionClass
from kakeyalogic.state import FieldState


@dataclass(frozen=True)
class OverlapIssue:
    cluster_id: str
    code: str
    detail: str
    edge_ids: tuple[str, ...] = ()


@dataclass(frozen=True)
class OverlapReport:
    ok: bool
    issues: tuple[OverlapIssue, ...] = ()

    def to_dict(self) -> dict:
        return {
            "ok": self.ok,
            "issues": [
                {"cluster_id": i.cluster_id, "code": i.code, "detail": i.detail,
                 "edge_ids": list(i.edge_ids)}
                for i in self.issues
            ],
        }


def check_overlap(state: FieldState, evaluated: dict[str, EvaluatedEdge]) -> OverlapReport:
    """Shared clusters must keep independently recoverable grain bundles.

    Authority is never created by wording, proximity, or type labels.
    """
    issues: list[OverlapIssue] = []
    for cluster in state.clusters.values():
        cluster_edges = tuple(sorted(
            edge_id for edge_id, item in evaluated.items()
            if item.edge.cluster_id == cluster.cluster_id
        ))
        if len(set(cluster.member_direction_ids)) != len(cluster.member_direction_ids):
            issues.append(
                OverlapIssue(
                    cluster.cluster_id,
                    "merged_direction_identity",
                    "cluster member list collapsed distinct direction identities",
                    cluster_edges,
                )
            )
        for direction_id in cluster.member_direction_ids:
            direction = state.directions.get(direction_id)
            grains = direction.required_grains if direction else SAVER
            missing = [q.value for q in grains if not any(
                direction_id in item.edge.direction_ids
                and item.bundle.cell(direction_id, q) is not None
                for item in evaluated.values()
            )]
            if missing:
                issues.append(
                    OverlapIssue(
                        cluster.cluster_id,
                        "missing_independent_grain_state",
                        f"direction {direction_id} lacks independently inspectable grains: {', '.join(missing)}",
                        cluster_edges,
                    )
                )
    for item in evaluated.values():
        if item.edge.authority_inherited_from_cluster:
            issues.append(
                OverlapIssue(
                    item.edge.cluster_id,
                    "authority_from_proximity",
                    f"{item.edge.edge_id} inherited authority from cluster membership; "
                    "authority is never created by proximity",
                    (item.edge_id,),
                )
            )
    return OverlapReport(ok=not issues, issues=tuple(issues))


def enforce_overlap(
    evaluated: dict[str, EvaluatedEdge], report: OverlapReport
) -> dict[str, EvaluatedEdge]:
    """Retain declared grain evidence, but reject structurally invalid edges.

    The receipt names the independent admission failures rather than changing
    a declared grain observation into an invented measurement.
    """
    result = dict(evaluated)
    for issue in report.issues:
        for edge_id in issue.edge_ids:
            item = result[edge_id]
            result[edge_id] = replace(
                item,
                classification=TransitionClass.FAILED,
                admission_issues=item.admission_issues + (issue.code + ": " + issue.detail,),
            )
    return result

"""Command-line mathematics application: python -m kakeyalogic.prover."""

import argparse
import json
import sys
from pathlib import Path

from .engine import load_receipt, run, verify


def _describe(receipt):
    print(receipt["status"])
    print(receipt["problem"]["statement"])
    for assumption in receipt["problem"].get("assumptions", []):
        print("  Given: " + assumption)
    if "reason" in receipt:
        print(receipt["reason"])
    certificate = receipt["certificate"]
    if not certificate:
        return
    if "assignment" in certificate:
        print("Counterexample: " + json.dumps(certificate["assignment"], sort_keys=True))
    if "solution" in certificate:
        solution = certificate["solution"]
        if solution["classification"] == "UNIQUE":
            print("; ".join(name + " = " + value for name, value in
                            zip(solution["variables"], solution["particular"])) or "Unique empty assignment.")
        elif solution["classification"] == "PARAMETRIC":
            print("Variable order: " + ", ".join(solution["variables"]))
            print("Particular vector: " + ", ".join(solution["particular"]))
            for parameter, vector in zip(solution["parameters"], solution["basis"]):
                print("  + " + parameter + " * (" + ", ".join(vector) + ")")
        else:
            print("Replayed row operations establish 0 = 1; no rational solution.")
    print("Certificate checked by Frontier Math Rework.")


def main(argv=None):
    parser = argparse.ArgumentParser(description="Frontier Math Rework — independent exact proof checker and solver")
    commands = parser.add_subparsers(dest="command", required=True)
    for command, help_text in (("prove", "Classical propositional theorem proving"),
                               ("identity", "Polynomial identities over Q"),
                               ("solve", "Linear equations over Q, separated by semicolons")):
        child = commands.add_parser(command, help=help_text)
        child.add_argument("statement")
        child.add_argument("--json", action="store_true", help="Print the full replayable receipt")
        child.add_argument("--out", type=Path, help="Save a JSON proof receipt")
        if command == "prove":
            child.add_argument("--given", action="append", default=[], help="Explicit hypothesis; repeatable")
            child.add_argument("--max-steps", type=int, default=5000)
        if command == "solve":
            child.add_argument("--variables", nargs="+", help="Explicit variable order, including unused variables")
    check = commands.add_parser("check", help="Independently replay a saved certificate")
    check.add_argument("file", type=Path)
    check.add_argument("--expect", help="Require this exact statement, kind and hypotheses below")
    check.add_argument("--kind", choices=("logic", "identity", "linear"))
    check.add_argument("--given", action="append", default=[])
    check.add_argument("--variables", nargs="+")
    check.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)
    try:
        if args.command == "check":
            if (args.expect is None) != (args.kind is None):
                parser.error("Use --expect and --kind together to bind the full expected problem.")
            if args.expect is None and (args.given or args.variables):
                parser.error("--given and --variables require --expect and --kind.")
            if args.file.stat().st_size > 4_000_000:
                raise ValueError("Certificate file limit is 4 MB.")
            receipt = load_receipt(args.file.read_text(encoding="utf-8"))
            expected = None
            if args.expect is not None:
                expected = {"kind": args.kind, "statement": args.expect}
                if args.kind == "logic":
                    expected["assumptions"] = args.given
                elif args.given:
                    parser.error("--given is supported only for logic.")
                if args.variables is not None:
                    if args.kind != "linear":
                        parser.error("--variables is supported only for linear systems.")
                    expected["variables"] = args.variables
            result = verify(receipt, expected_problem=expected)
            if args.json:
                print(json.dumps(result, indent=2))
            elif result["valid"]:
                _describe(receipt)
            else:
                print("REJECTED: " + result["reason"])
            return 0 if result["valid"] else 1
        problem = {"kind": {"prove": "logic", "identity": "identity", "solve": "linear"}[args.command],
                   "statement": args.statement}
        if args.command == "prove":
            problem["assumptions"] = args.given
        if args.command == "solve" and args.variables is not None:
            problem["variables"] = args.variables
        receipt = run(problem, max_steps=getattr(args, "max_steps", 5000))
        encoded = json.dumps(receipt, ensure_ascii=False, indent=2) + "\n"
        if args.out:
            args.out.write_text(encoded, encoding="utf-8")
        if args.json:
            print(encoded, end="")
        else:
            _describe(receipt)
            if args.out:
                print("Saved: " + str(args.out))
        return 2 if receipt["certificate"] is None else 0
    except (OSError, ValueError, RecursionError) as error:
        print("ERROR: " + str(error), file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())

"""Trusted exact polynomial arithmetic over Q and affine-system parsing.

Sparse monomials are sorted tuples of variable names. All coefficients use
Fraction; division is permitted only by nonzero rational constants.
"""

import re
from fractions import Fraction

from .syntax import InvalidProblem, tokenize

MAX_TERMS = 1024
MAX_BITS = 4096
_TOKEN = re.compile(r"\*\*|[0-9]+|[A-Za-z][A-Za-z0-9_]*|[+*/^()\-]")
_NAME = re.compile(r"[A-Za-z][A-Za-z0-9_]*\Z")


def bounded(poly):
    """Canonicalize zero terms and keep exact arithmetic within fixed bounds."""
    poly = {monomial: coefficient for monomial, coefficient in poly.items() if coefficient}
    if len(poly) > MAX_TERMS or any(len(monomial) > 64 for monomial in poly):
        raise InvalidProblem("Polynomial size limit exceeded.")
    if any(max(abs(q.numerator).bit_length(), q.denominator.bit_length()) > MAX_BITS
           for q in poly.values()):
        raise InvalidProblem("Exact coefficient size limit exceeded.")
    return poly


def add(left, right):
    result = left.copy()
    for monomial, coefficient in right.items():
        result[monomial] = result.get(monomial, Fraction(0)) + coefficient
    return bounded(result)


def scale(poly, scalar):
    return bounded({monomial: coefficient * scalar for monomial, coefficient in poly.items()})


def multiply(left, right):
    result = {}
    if len(left) * len(right) > 100_000:
        raise InvalidProblem("Polynomial multiplication budget exceeded.")
    for first, a in left.items():
        for second, b in right.items():
            monomial = tuple(sorted(first + second))
            result[monomial] = result.get(monomial, Fraction(0)) + a * b
    return bounded(result)


def parse_polynomial(source):
    """Parse explicit rational polynomial syntax; no calls or symbolic inverses."""
    tokens = tokenize(source, _TOKEN, 256)
    pos = 0

    def take(token):
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == token:
            pos += 1
            return True
        return False

    def atom(depth):
        nonlocal pos
        if depth > 40:
            raise InvalidProblem("Algebra nesting limit exceeded.")
        if take("("):
            value = expression(depth + 1)
            if not take(")"):
                raise InvalidProblem("Missing closing parenthesis.")
            return value
        if pos >= len(tokens):
            raise InvalidProblem("Expected an integer, variable, or parenthesis.")
        token = tokens[pos]
        pos += 1
        if token.isdigit():
            return bounded({(): Fraction(int(token))})
        if _NAME.fullmatch(token):
            return {(token,): Fraction(1)}
        raise InvalidProblem("Expected an integer, variable, or parenthesis.")

    def power(depth):
        nonlocal pos
        value = atom(depth)
        if take("^") or take("**"):
            if pos >= len(tokens) or not tokens[pos].isdigit():
                raise InvalidProblem("An exponent must be an integer from 0 through 16.")
            exponent = int(tokens[pos])
            pos += 1
            if exponent > 16:
                raise InvalidProblem("An exponent must be an integer from 0 through 16.")
            base, value = value, {(): Fraction(1)}
            for _ in range(exponent):
                value = multiply(value, base)
        return value

    def signed(depth):
        if depth > 40:
            raise InvalidProblem("Algebra nesting limit exceeded.")
        if take("+"):
            return signed(depth + 1)
        if take("-"):
            return scale(signed(depth + 1), -1)
        return power(depth)

    def product(depth):
        value = signed(depth)
        while pos < len(tokens) and tokens[pos] in ("*", "/"):
            divide = take("/")
            if not divide:
                take("*")
            other = signed(depth)
            if divide:
                if any(monomial for monomial in other) or not other.get((), 0):
                    raise InvalidProblem("Divide only by a nonzero rational constant.")
                value = scale(value, 1 / other[()])
            else:
                value = multiply(value, other)
        return value

    def expression(depth):
        value = product(depth)
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            subtract = take("-")
            if not subtract:
                take("+")
            other = product(depth)
            value = add(value, scale(other, -1) if subtract else other)
        return value

    value = expression(0)
    if pos != len(tokens):
        raise InvalidProblem("Unexpected algebra token: %s." % tokens[pos])
    if len(variables(value)) > 16:
        raise InvalidProblem("At most 16 variables are supported.")
    return value


def variables(poly):
    return set().union(*(set(monomial) for monomial in poly))


def equation(source):
    if not isinstance(source, str) or source.count("=") != 1:
        raise InvalidProblem("An equation must contain exactly one '='.")
    left, right = source.split("=")
    return parse_polynomial(left), parse_polynomial(right)


def normal_form(poly):
    return [[list(monomial), str(coefficient)] for monomial, coefficient in sorted(poly.items())]


def evaluate(poly, assignment):
    result = Fraction(0)
    for monomial, coefficient in poly.items():
        for name in monomial:
            coefficient *= assignment[name]
        result += coefficient
    return result


def rational(text):
    """Read a bounded certificate scalar in canonical Fraction string form."""
    if not isinstance(text, str) or len(text) > 2500:
        raise InvalidProblem("A certificate scalar must be a bounded rational string.")
    try:
        value = Fraction(text)
    except (ValueError, ZeroDivisionError) as error:
        raise InvalidProblem("Invalid certificate rational.") from error
    bounded({(): value})
    if str(value) != text:
        raise InvalidProblem("Certificate rationals must use canonical form, e.g. '1/2'.")
    return value


def linear_problem(problem):
    equations = problem["statement"].split(";")
    if not 1 <= len(equations) <= 32:
        raise InvalidProblem("Supply between 1 and 32 equations, separated by semicolons.")
    polys = [add(left, scale(right, -1)) for left, right in map(equation, equations)]
    if any(len(monomial) > 1 for poly in polys for monomial in poly):
        raise InvalidProblem("The linear solver accepts affine equations over Q.")
    # Keep syntactically present variables even if normalization cancels them.
    # x - x = 0 describes every rational x, rather than a zero-variable solution.
    names = {token for source in equations for token in tokenize(source.replace("=", " "), _TOKEN)
             if _NAME.fullmatch(token)}
    declared = problem.get("variables")
    if declared is None:
        declared = sorted(names)
    if (not isinstance(declared, list) or len(declared) > 16
            or any(not isinstance(name, str) or not _NAME.fullmatch(name) for name in declared)
            or len(set(declared)) != len(declared) or not names.issubset(declared)):
        raise InvalidProblem("Declare distinct variable names covering every equation variable (max 16).")
    matrix = [[poly.get((name,), Fraction(0)) for name in declared]
              + [-poly.get((), Fraction(0))] for poly in polys]
    return declared, matrix


def matrix_json(matrix):
    return [[str(value) for value in row] for row in matrix]


def solution_from_rref(names, matrix):
    """Trusted interpretation of an already checked reduced row echelon form."""
    width = len(names)
    pivots, previous, zero_seen = {}, -1, False
    for index, row in enumerate(matrix):
        pivot = next((j for j, value in enumerate(row) if value), None)
        if pivot is None:
            zero_seen = True
            continue
        if zero_seen or pivot <= previous or row[pivot] != 1:
            raise InvalidProblem("Certificate matrix is not in reduced row echelon form.")
        if any(other[pivot] != 0 for k, other in enumerate(matrix) if k != index):
            raise InvalidProblem("A pivot column is not reduced.")
        previous = pivot
        pivots[pivot] = index
    if width in pivots:
        return {"classification": "INCONSISTENT", "contradiction_row": pivots[width]}
    free = [j for j in range(width) if j not in pivots]
    particular = [Fraction(0)] * width
    basis = []
    for column, index in pivots.items():
        particular[column] = matrix[index][-1]
    for column in free:
        vector = [Fraction(0)] * width
        vector[column] = Fraction(1)
        for pivot, index in pivots.items():
            vector[pivot] = -matrix[index][column]
        basis.append([str(value) for value in vector])
    return {"classification": "PARAMETRIC" if free else "UNIQUE", "variables": names,
            "particular": [str(value) for value in particular], "basis": basis,
            "parameters": [names[j] for j in free]}

"""Problem-bound proof receipts and the public run/verify API."""

import hashlib
import json

from . import kernel
from .syntax import BudgetExceeded, InvalidProblem

SCHEMA = "frontier-math-rework/certificate-v1"
# Retain replay of previously saved records; new output uses the current name.
_PREVIOUS_SCHEMA = "love-labs-prover/0.1"


def fingerprint(problem):
    """Bind exact source, assumptions, domain/kind, and declared variable order."""
    source = json.dumps(problem, ensure_ascii=True, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(source.encode("utf-8")).hexdigest()


def run(problem, *, max_steps=5000):
    """Produce a certificate and return success only after independent replay.

    UNKNOWN and INVALID always carry a null certificate. No conclusion is
    inferred from search exhaustion. Inputs must already be in the formal DSL.
    """
    receipt = {"schema": SCHEMA, "problem": problem, "problem_sha256": None,
               "status": "INVALID", "certificate": None, "statistics": {}}
    try:
        kind = kernel.validate_problem(problem)
        receipt["problem_sha256"] = fingerprint(problem)
        if type(max_steps) is not int or not 1 <= max_steps <= kernel.MAX_NODES:
            raise InvalidProblem("Search budget must be an integer from 1 through 20000.")
        # Lazy imports let certificate verification run without either producer.
        from . import search, solver  # pylint: disable=import-outside-toplevel
        if kind == "logic":
            certificate, statistics = search.prove(problem, max_steps)
        elif kind == "identity":
            certificate, statistics = solver.identity(problem)
        else:
            certificate, statistics = solver.linear(problem)
        status = kernel.check(problem, certificate)
        return dict(receipt, status=status, certificate=certificate, statistics=statistics)
    except (BudgetExceeded, RecursionError) as error:
        receipt.update(status="UNKNOWN", reason=str(error) or "Recursion budget exhausted.")
    except (InvalidProblem, ValueError, TypeError, KeyError, OverflowError) as error:
        receipt.update(reason=str(error))
    return receipt


def verify(receipt, *, expected_problem=None):
    """Re-derive the status; ignore producer statistics and trust no saved flag.

    expected_problem binds a received certificate to the caller's own complete
    problem. A digest alone is integrity metadata, not authentication.
    """
    try:
        if not isinstance(receipt, dict):
            raise InvalidProblem("A receipt must be a JSON object.")
        required = {"schema", "problem", "problem_sha256", "status", "certificate", "statistics"}
        if not required.issubset(receipt) or not set(receipt).issubset(required | {"reason"}):
            raise InvalidProblem("Malformed proof receipt.")
        if receipt["schema"] not in (SCHEMA, _PREVIOUS_SCHEMA):
            raise InvalidProblem("Unsupported proof receipt version.")
        problem = receipt["problem"]
        kernel.validate_problem(problem)
        if expected_problem is not None and fingerprint(problem) != fingerprint(expected_problem):
            raise InvalidProblem("Receipt does not match the expected problem and assumptions.")
        if receipt["problem_sha256"] != fingerprint(problem):
            raise InvalidProblem("Problem digest does not match its exact source.")
        if not isinstance(receipt["statistics"], dict):
            raise InvalidProblem("Malformed producer statistics.")
        status = kernel.check(problem, receipt["certificate"])
        if receipt["status"] != status:
            raise InvalidProblem("Saved status disagrees with the checked mathematical conclusion.")
        return {"valid": True, "status": status, "problem_sha256": receipt["problem_sha256"]}
    except (ValueError, TypeError, KeyError, IndexError, RecursionError, OverflowError) as error:
        return {"valid": False, "status": "REJECTED", "reason": str(error)}


def load_receipt(source):
    """Read bounded JSON and reject ambiguous duplicate fields and nonfinite values."""
    if not isinstance(source, str) or len(source.encode("utf-8")) > 4_000_000:
        raise InvalidProblem("Certificate file limit is 4 MB.")

    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise InvalidProblem("Duplicate JSON field: " + key)
            result[key] = value
        return result

    def reject_constant(value):
        raise InvalidProblem("Nonfinite JSON value: " + value)

    try:
        return json.loads(source, object_pairs_hook=pairs, parse_constant=reject_constant)
    except RecursionError as error:
        raise InvalidProblem("Certificate JSON nesting limit exceeded.") from error

"""Certificate checker. This module never imports search or solver code.

The trusted base is this checker, syntax.py, algebra.py, Python's integers and
fractions. The supported logical theory is classical propositional logic;
algebra is over the rational field. No extra axioms can be loaded.
"""

from . import algebra
from .syntax import InvalidProblem, evaluate, logic_problem

MAX_NODES = 20_000
MAX_OPERATIONS = 4096


def fields(value, required):
    """Reject incomplete or differently shaped certificate objects."""
    if not isinstance(value, dict) or set(value) != set(required.split()):
        raise InvalidProblem("Malformed certificate object; expected fields: " + required)


def index(value, size):
    if type(value) is not int or not 0 <= value < size:
        raise InvalidProblem("Invalid certificate index.")
    return value


def validate_problem(problem):
    if not isinstance(problem, dict) or not isinstance(problem.get("statement"), str):
        raise InvalidProblem("A problem requires a text statement.")
    kind = problem.get("kind")
    allowed = {"logic": {"kind", "statement", "assumptions"},
               "identity": {"kind", "statement"},
               "linear": {"kind", "statement", "variables"}}
    if not isinstance(kind, str) or kind not in allowed or not set(problem).issubset(allowed[kind]):
        raise InvalidProblem("Problem kind must be logic, identity, or linear, with explicit fields.")
    if len(problem["statement"]) > 16_384:
        raise InvalidProblem("Problem statement is too large.")
    return kind


def check_logic(problem, certificate):
    left, right, names = logic_problem(problem)
    if certificate.get("method") == "countermodel":
        fields(certificate, "method assignment")
        assignment = certificate["assignment"]
        if (not isinstance(assignment, dict) or set(assignment) != names
                or any(type(value) is not bool for value in assignment.values())):
            raise InvalidProblem("Countermodel must assign a Boolean to every proposition.")
        if not all(evaluate(item, assignment) for item in left) or evaluate(right[0], assignment):
            raise InvalidProblem("Assignment does not refute the original sequent.")
        return "DISPROVED"
    fields(certificate, "method nodes root")
    if certificate["method"] != "sequent":
        raise InvalidProblem("Unknown logical certificate method.")
    nodes = certificate["nodes"]
    if not isinstance(nodes, list) or not 1 <= len(nodes) <= MAX_NODES:
        raise InvalidProblem("Proof node limit exceeded or empty proof.")
    root = index(certificate["root"], len(nodes))
    if root != len(nodes) - 1:
        raise InvalidProblem("The root must be the final proof node.")
    todo, seen, work = [(root, left, right)], set(), 0
    while todo:
        node_id, gamma, delta = todo.pop()
        work += 1
        if work > MAX_NODES:
            raise InvalidProblem("Certificate replay budget exceeded.")
        seen.add(node_id)
        node = nodes[node_id]
        if not isinstance(node, dict):
            raise InvalidProblem("A proof node must be an object.")
        rule = node.get("rule")
        if rule in ("id", "bottom_left", "top_right"):
            fields(node, "rule")
            valid = (rule == "id" and bool(set(gamma).intersection(delta))
                     or rule == "bottom_left" and any(f.op == "false" for f in gamma)
                     or rule == "top_right" and any(f.op == "true" for f in delta))
            if not valid:
                raise InvalidProblem("Unjustified proof leaf.")
            continue
        fields(node, "rule index children")
        if rule not in {"true_left", "false_right", "not_left", "not_right",
                        "and_left", "and_right", "or_left", "or_right", "imp_left", "imp_right"}:
            raise InvalidProblem("Unknown inference rule.")
        side = gamma if rule.endswith("_left") else delta
        selected = index(node["index"], len(side))
        principal = side[selected]
        if principal.op != rule.rsplit("_", 1)[0]:
            raise InvalidProblem("Inference rule does not match its principal formula.")
        rest = side[:selected] + side[selected + 1:]
        args = principal.args
        # Independently specified two-sided classical sequent rules.
        if rule == "true_left":
            premises = [(rest, delta)]
        elif rule == "false_right":
            premises = [(gamma, rest)]
        elif rule == "not_left":
            premises = [(rest, delta + (args[0],))]
        elif rule == "not_right":
            premises = [(gamma + (args[0],), rest)]
        elif rule == "and_left":
            premises = [(rest + args, delta)]
        elif rule == "and_right":
            premises = [(gamma, rest + (args[0],)), (gamma, rest + (args[1],))]
        elif rule == "or_left":
            premises = [(rest + (args[0],), delta), (rest + (args[1],), delta)]
        elif rule == "or_right":
            premises = [(gamma, rest + args)]
        elif rule == "imp_left":
            premises = [(rest, delta + (args[0],)), (rest + (args[1],), delta)]
        else:  # imp_right
            premises = [(gamma + (args[0],), rest + (args[1],))]
        children = node["children"]
        if not isinstance(children, list) or len(children) != len(premises):
            raise InvalidProblem("Incorrect premise count.")
        for child, (before, after) in zip(children, premises):
            # Backward-only references also rule out cyclic proof certificates.
            index(child, node_id)
            todo.append((child, before, after))
    if seen != set(range(len(nodes))):
        raise InvalidProblem("Certificate contains unreachable proof nodes.")
    return "PROVED"


def check_identity(problem, certificate):
    left, right = algebra.equation(problem["statement"])
    if certificate.get("method") == "normalization":
        fields(certificate, "method normal_form")
        if left != right or certificate["normal_form"] != algebra.normal_form(left):
            raise InvalidProblem("Polynomial normal forms do not establish this identity.")
        return "PROVED"
    fields(certificate, "method assignment")
    if certificate["method"] != "evaluation":
        raise InvalidProblem("Unknown algebraic certificate method.")
    assignment = certificate["assignment"]
    if not isinstance(assignment, dict) or set(assignment) != algebra.variables(left) | algebra.variables(right):
        raise InvalidProblem("A counterexample must assign every polynomial variable.")
    assignment = {name: algebra.rational(value) for name, value in assignment.items()}
    if algebra.evaluate(left, assignment) == algebra.evaluate(right, assignment):
        raise InvalidProblem("Assignment does not refute the polynomial identity.")
    return "DISPROVED"


def check_linear(problem, certificate):
    fields(certificate, "method operations rref solution")
    if certificate["method"] != "row-reduction":
        raise InvalidProblem("Unknown linear certificate method.")
    names, matrix = algebra.linear_problem(problem)
    operations = certificate["operations"]
    if not isinstance(operations, list) or len(operations) > MAX_OPERATIONS:
        raise InvalidProblem("Row operation limit exceeded.")
    for operation in operations:
        if not isinstance(operation, dict):
            raise InvalidProblem("A row operation must be an object.")
        op = operation.get("op")
        if op == "swap":
            fields(operation, "op a b")
            first, second = index(operation["a"], len(matrix)), index(operation["b"], len(matrix))
            matrix[first], matrix[second] = matrix[second], matrix[first]
        elif op == "scale":
            fields(operation, "op row factor")
            row = index(operation["row"], len(matrix))
            factor = algebra.rational(operation["factor"])
            if not factor:
                raise InvalidProblem("Scaling a row by zero is not reversible.")
            matrix[row] = [factor * value for value in matrix[row]]
        elif op == "add":
            fields(operation, "op target source factor")
            target = index(operation["target"], len(matrix))
            source = index(operation["source"], len(matrix))
            if target == source:
                raise InvalidProblem("Row addition must use distinct rows.")
            factor = algebra.rational(operation["factor"])
            matrix[target] = [a + factor * b for a, b in zip(matrix[target], matrix[source])]
        else:
            raise InvalidProblem("Unknown row operation.")
        for row in matrix:
            for value in row:
                algebra.bounded({(): value})
    if certificate["rref"] != algebra.matrix_json(matrix):
        raise InvalidProblem("Claimed matrix does not match the replayed row operations.")
    solution = algebra.solution_from_rref(names, matrix)
    if (certificate["solution"] != solution
            or (solution["classification"] == "INCONSISTENT"
                and type(certificate["solution"].get("contradiction_row")) is not int)):
        raise InvalidProblem("Claimed solution does not match the checked echelon form.")
    return solution["classification"]


def check(problem, certificate):
    """Check the actual problem and proof; return only the derived status."""
    kind = validate_problem(problem)
    if not isinstance(certificate, dict):
        raise InvalidProblem("Missing certificate object.")
    return {"logic": check_logic, "identity": check_identity, "linear": check_linear}[kind](problem, certificate)

"""Untrusted deterministic sequent search. Only kernel replay admits a proof."""

from .syntax import BudgetExceeded, logic_problem


def prove(problem, max_steps=5000):
    left, right, names = logic_problem(problem)
    nodes, steps = [], 0

    def emit(rule, selected=None, children=None):
        node = {"rule": rule}
        if selected is not None:
            node.update(index=selected, children=children)
        nodes.append(node)
        return len(nodes) - 1

    def visit(gamma, delta):
        nonlocal steps
        steps += 1
        if steps > max_steps:
            raise BudgetExceeded("Logical search step budget exhausted.")
        if set(gamma).intersection(delta):
            return emit("id"), None
        if any(item.op == "false" for item in gamma):
            return emit("bottom_left"), None
        if any(item.op == "true" for item in delta):
            return emit("top_right"), None
        for side_name, side in (("left", gamma), ("right", delta)):
            for selected, formula in enumerate(side):
                if formula.op == "atom":
                    continue
                rest = side[:selected] + side[selected + 1:]
                op, args = formula.op, formula.args
                if side_name == "left":
                    if op == "true":
                        goals = [(rest, delta)]
                    elif op == "not":
                        goals = [(rest, delta + args)]
                    elif op == "and":
                        goals = [(rest + args, delta)]
                    elif op == "or":
                        goals = [(rest + (a,), delta) for a in args]
                    else:  # implication
                        goals = [(rest, delta + (args[0],)), (rest + (args[1],), delta)]
                else:
                    if op == "false":
                        goals = [(gamma, rest)]
                    elif op == "not":
                        goals = [(gamma + args, rest)]
                    elif op == "and":
                        goals = [(gamma, rest + (a,)) for a in args]
                    elif op == "or":
                        goals = [(gamma, rest + args)]
                    else:
                        goals = [(gamma + (args[0],), rest + (args[1],))]
                children = []
                for before, after in goals:
                    child, witness = visit(before, after)
                    if witness is not None:
                        return None, witness
                    children.append(child)
                return emit(op + "_" + side_name, selected, children), None
        assignment = {name: False for name in sorted(names)}
        assignment.update({formula.name: True for formula in gamma})
        return None, assignment

    root, countermodel = visit(left, right)
    certificate = ({"method": "countermodel", "assignment": countermodel}
                   if countermodel is not None else {"method": "sequent", "nodes": nodes, "root": root})
    return certificate, {"search_steps": steps}

"""Untrusted exact-algebra certificate producers."""

from fractions import Fraction

from . import algebra


def identity(problem):
    left, right = algebra.equation(problem["statement"])
    if left == right:
        return {"method": "normalization", "normal_form": algebra.normal_form(left)}, {}
    difference = algebra.add(left, algebra.scale(right, -1))
    assignment = {}
    # Specialize one variable at a time while keeping the polynomial nonzero.
    # A nonzero degree-d polynomial has at most d roots over Q.
    for name in sorted(algebra.variables(left) | algebra.variables(right)):
        degree = max((monomial.count(name) for monomial in difference), default=0)
        for candidate in range(degree + 1):
            specialized = {}
            for monomial, coefficient in difference.items():
                reduced = tuple(variable for variable in monomial if variable != name)
                coefficient *= Fraction(candidate) ** monomial.count(name)
                specialized[reduced] = specialized.get(reduced, Fraction(0)) + coefficient
            specialized = algebra.bounded(specialized)
            if specialized:
                assignment[name] = str(candidate)
                difference = specialized
                break
        else:
            raise ValueError("Failed to construct a nonidentity witness.")
    return {"method": "evaluation", "assignment": assignment}, {}


def linear(problem):
    names, matrix = algebra.linear_problem(problem)
    operations, pivot_row = [], 0
    # Include the augmented column so inconsistent systems also reach full RREF.
    for column in range(len(names) + 1):
        selected = next((row for row in range(pivot_row, len(matrix)) if matrix[row][column]), None)
        if selected is None:
            continue
        if selected != pivot_row:
            matrix[selected], matrix[pivot_row] = matrix[pivot_row], matrix[selected]
            operations.append({"op": "swap", "a": selected, "b": pivot_row})
        factor = 1 / matrix[pivot_row][column]
        if factor != 1:
            matrix[pivot_row] = [factor * value for value in matrix[pivot_row]]
            operations.append({"op": "scale", "row": pivot_row, "factor": str(factor)})
        for row in range(len(matrix)):
            if row == pivot_row or not matrix[row][column]:
                continue
            factor = -matrix[row][column]
            matrix[row] = [a + factor * b for a, b in zip(matrix[row], matrix[pivot_row])]
            operations.append({"op": "add", "target": row, "source": pivot_row, "factor": str(factor)})
        for row in matrix:
            for value in row:
                algebra.bounded({(): value})
        pivot_row += 1
        if pivot_row == len(matrix):
            break
    return {"method": "row-reduction", "operations": operations,
            "rref": algebra.matrix_json(matrix), "solution": algebra.solution_from_rref(names, matrix)}, {
                "row_operations": len(operations)}

"""Trusted syntax for finite classical propositional logic.

No Python evaluation, user-defined inference rules, or implicit assumptions.
Equivalence is an abbreviation for two implications.
"""

import re
from dataclasses import dataclass
from typing import Tuple


class InvalidProblem(ValueError):
    """The input is outside the declared language or its resource bounds."""


class BudgetExceeded(ValueError):
    """Search stopped without a mathematical conclusion."""


@dataclass(frozen=True)
class Formula:
    """A proposition in the trusted abstract syntax."""

    op: str
    args: Tuple["Formula", ...] = ()
    name: str = ""


_TOKEN = re.compile(r"<->|->|[~&|()]|[A-Za-z][A-Za-z0-9_]*")
_UNICODE = str.maketrans({"¬": "~", "∧": "&", "∨": "|", "→": "->",
                         "↔": "<->", "⊥": "false", "⊤": "true"})


def tokenize(source, pattern, limit=256):
    """Tokenize the entire source; never skip an unrecognized character."""
    if not isinstance(source, str) or not source.strip() or len(source) > 4096:
        raise InvalidProblem("Enter a nonempty expression of at most 4096 characters.")
    tokens, pos = [], 0
    while pos < len(source):
        if source[pos].isspace():
            pos += 1
            continue
        match = pattern.match(source, pos)
        if match is None:
            raise InvalidProblem("Unexpected character at position %d." % (pos + 1))
        tokens.append(match.group())
        pos = match.end()
        if len(tokens) > limit:
            raise InvalidProblem("Expression token limit exceeded.")
    return tokens


def parse_formula(source):
    """Parse ~, &, |, -> (right associative), and <-> in that precedence order."""
    if not isinstance(source, str):
        raise InvalidProblem("A proposition must be text.")
    tokens = tokenize(source.translate(_UNICODE), _TOKEN, 120)
    pos = 0

    def take(token):
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == token:
            pos += 1
            return True
        return False

    def atom(depth):
        nonlocal pos
        if depth > 40:
            raise InvalidProblem("Proposition nesting limit exceeded.")
        if take("~"):
            return Formula("not", (atom(depth + 1),))
        if take("("):
            value = equiv(depth + 1)
            if not take(")"):
                raise InvalidProblem("Missing closing parenthesis.")
            return value
        if pos >= len(tokens) or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", tokens[pos]):
            raise InvalidProblem("Expected a proposition name or parenthesis.")
        name = tokens[pos]
        pos += 1
        return Formula(name) if name in ("true", "false") else Formula("atom", name=name)

    def conjunction(depth):
        value = atom(depth)
        while take("&"):
            value = Formula("and", (value, atom(depth)))
        return value

    def disjunction(depth):
        value = conjunction(depth)
        while take("|"):
            value = Formula("or", (value, conjunction(depth)))
        return value

    def implication(depth):
        if depth > 40:
            raise InvalidProblem("Proposition nesting limit exceeded.")
        value = disjunction(depth)
        if take("->"):
            value = Formula("imp", (value, implication(depth + 1)))
        return value

    def equiv(depth):
        value = implication(depth)
        while take("<->"):
            other = implication(depth)
            value = Formula("and", (Formula("imp", (value, other)),
                                    Formula("imp", (other, value))))
        return value

    result = equiv(0)
    if pos != len(tokens):
        raise InvalidProblem("Unexpected token: %s." % tokens[pos])
    # Expanding nested equivalences can be exponential; bound the actual tree.
    todo, count = [result], 0
    while todo:
        current = todo.pop()
        count += 1
        if count > 512:
            raise InvalidProblem("Expanded proposition is too large.")
        todo.extend(current.args)
    return result


def atoms(formula):
    """Collect names without assigning them truth values."""
    if formula.op == "atom":
        return {formula.name}
    return set().union(*(atoms(arg) for arg in formula.args))


def evaluate(formula, assignment):
    """Classical Boolean semantics used only to check counterexamples."""
    op, args = formula.op, formula.args
    if op == "atom":
        return assignment[formula.name]
    if op in ("true", "false"):
        return op == "true"
    if op == "not":
        return not evaluate(args[0], assignment)
    left, right = (evaluate(arg, assignment) for arg in args)
    if op == "and":
        return left and right
    if op == "or":
        return left or right
    if op == "imp":
        return not left or right
    raise InvalidProblem("Unknown logical connective.")


def logic_problem(problem):
    """Preserve all explicitly supplied hypotheses in the checked sequent."""
    assumptions = problem.get("assumptions", [])
    if not isinstance(assumptions, list) or len(assumptions) > 16:
        raise InvalidProblem("Supply at most 16 explicit assumptions.")
    left = tuple(parse_formula(item) for item in assumptions)
    right = (parse_formula(problem["statement"]),)
    names = set().union(*(atoms(item) for item in left + right))
    if len(names) > 16:
        raise InvalidProblem("At most 16 proposition names are supported per problem.")
    return left, right, names

"""Typed field state: objects, directions, candidate transformations, interior samples."""

from __future__ import annotations

from dataclasses import dataclass, field, replace
from typing import Mapping, Sequence

from kakeyalogic.grains import (
    Grain,
    GrainBundle,
    GrainCell,
    Outcome,
    SAVER,
    parse_grain,
    parse_outcome,
)


@dataclass(frozen=True)
class TypedObject:
    object_id: str
    direction_id: str
    type: str
    content: str
    held: bool = True
    recoverable: bool = True
    role: str = ""
    version: str = "1"
    provenance: str = ""
    authority: str = ""
    cluster_id: str = ""
    notes: str = ""

    def to_dict(self) -> dict:
        return {
            "object_id": self.object_id,
            "direction_id": self.direction_id,
            "type": self.type,
            "content": self.content,
            "held": self.held,
            "recoverable": self.recoverable,
            "role": self.role,
            "version": self.version,
            "provenance": self.provenance,
            "authority": self.authority,
            "cluster_id": self.cluster_id,
            "notes": self.notes,
        }


@dataclass(frozen=True)
class Direction:
    direction_id: str
    required_grains: tuple[Grain, ...] = SAVER
    description: str = ""

    def to_dict(self) -> dict:
        return {
            "direction_id": self.direction_id,
            "required_grains": [g.value for g in self.required_grains],
            "description": self.description,
        }


@dataclass(frozen=True)
class InteriorSample:
    u: float
    outcomes: Mapping[Grain, Outcome]
    note: str = ""
    per_direction: Mapping[str, Mapping[Grain, Outcome]] | None = None

    def __post_init__(self) -> None:
        if not 0.0 <= self.u <= 1.0:
            raise ValueError(f"interior sample u={self.u} is outside [0, 1]")

    def outcomes_for(self, direction_id: str) -> Mapping[Grain, Outcome]:
        if self.per_direction and direction_id in self.per_direction:
            return self.per_direction[direction_id]
        return self.outcomes

    def to_dict(self) -> dict:
        payload = {
            "u": self.u,
            "outcomes": {g.value: o.value for g, o in self.outcomes.items()},
            "note": self.note,
        }
        if self.per_direction:
            payload["per_direction"] = {
                d: {g.value: o.value for g, o in grains.items()}
                for d, grains in self.per_direction.items()
            }
        return payload


@dataclass(frozen=True)
class CandidateEdge:
    """A candidate transformation e: src → dst with declared grain evidence."""

    edge_id: str
    src: str
    dst: str
    cost: float
    direction_ids: tuple[str, ...]
    required_grains: tuple[Grain, ...]
    declared: GrainBundle
    interior: tuple[InteriorSample, ...] = ()
    claimed_interior_scale: bool = False
    cluster_id: str = ""
    notes: str = ""
    authority_inherited_from_cluster: bool = False

    def __post_init__(self) -> None:
        if self.cost <= 0:
            raise ValueError(
                f"operational edge cost must be positive; {self.edge_id} has cost={self.cost}"
            )

    def required_pairs(self) -> tuple[tuple[str, Grain], ...]:
        return tuple((d, q) for d in self.direction_ids for q in self.required_grains)

    def to_dict(self) -> dict:
        return {
            "edge_id": self.edge_id,
            "src": self.src,
            "dst": self.dst,
            "cost": self.cost,
            "direction_ids": list(self.direction_ids),
            "required_grains": [g.value for g in self.required_grains],
            "declared": self.declared.to_dict(),
            "interior": [s.to_dict() for s in self.interior],
            "claimed_interior_scale": self.claimed_interior_scale,
            "cluster_id": self.cluster_id,
            "notes": self.notes,
            "authority_inherited_from_cluster": self.authority_inherited_from_cluster,
        }


@dataclass(frozen=True)
class OverlapCluster:
    cluster_id: str
    member_direction_ids: tuple[str, ...]
    representation_unit: str
    notes: str = ""


@dataclass
class FieldState:
    """Research state at one evaluation epoch.

    Unresolved and failed edges remain in `edges`. Deleting them would erase
    evidence and weaken later refinement.
    """

    state_id: str
    nodes: tuple[str, ...]
    directions: dict[str, Direction]
    objects: dict[str, TypedObject]
    edges: dict[str, CandidateEdge]
    clusters: dict[str, OverlapCluster] = field(default_factory=dict)
    allowed_boundary: tuple[str, ...] = ()
    confirmed_reachable: tuple[str, ...] = ()
    modeled_envelope: tuple[str, ...] = ()
    current: str = ""
    goal: str = ""
    epoch: int = 0
    notes: str = ""

    def copy(self) -> "FieldState":
        return FieldState(
            state_id=self.state_id,
            nodes=self.nodes,
            directions=dict(self.directions),
            objects={k: v for k, v in self.objects.items()},
            edges={k: v for k, v in self.edges.items()},
            clusters=dict(self.clusters),
            allowed_boundary=self.allowed_boundary,
            confirmed_reachable=self.confirmed_reachable,
            modeled_envelope=self.modeled_envelope,
            current=self.current,
            goal=self.goal,
            epoch=self.epoch,
            notes=self.notes,
        )

    def required_direction_ids(self) -> tuple[str, ...]:
        return tuple(sorted(self.directions))

    def objects_for(self, direction_id: str) -> list[TypedObject]:
        return [o for o in self.objects.values() if o.direction_id == direction_id]


def bundle_from_declared(
    direction_ids: Sequence[str],
    grains: Sequence[Grain],
    declared: Mapping[str, str],
    *,
    check: str,
    reason: str,
    evidence_refs: Sequence[str] = (),
    per_direction: Mapping[str, Mapping[str, str]] | None = None,
) -> GrainBundle:
    cells: list[GrainCell] = []
    for direction_id in direction_ids:
        local = per_direction.get(direction_id, {}) if per_direction else {}
        for grain in grains:
            raw = local.get(grain.value, declared.get(grain.value, Outcome.NOT_EVALUATED.value))
            cells.append(
                GrainCell(
                    direction_id=direction_id,
                    grain=grain,
                    outcome=parse_outcome(raw) if isinstance(raw, str) else raw,
                    check=check,
                    reason=reason,
                    evidence_refs=tuple(evidence_refs),
                )
            )
    return GrainBundle(cells=tuple(cells))


def parse_interior(raw_samples: Sequence[Mapping], grains: Sequence[Grain]) -> tuple[InteriorSample, ...]:
    samples: list[InteriorSample] = []
    for item in raw_samples:
        outcomes = {
            parse_grain(k): parse_outcome(v) for k, v in item.get("outcomes", {}).items()
        }
        per_dir = None
        if "per_direction" in item:
            per_dir = {
                d: {parse_grain(k): parse_outcome(v) for k, v in mapping.items()}
                for d, mapping in item["per_direction"].items()
            }
        samples.append(
            InteriorSample(
                u=float(item["u"]),
                outcomes=outcomes,
                note=item.get("note", ""),
                per_direction=per_dir,
            )
        )
        missing = [g for g in grains if g not in samples[-1].outcomes]
        if missing and per_dir is None:
            # Interior samples may omit grains; omitted grains stay NOT_EVALUATED at that u.
            filled = dict(samples[-1].outcomes)
            for g in missing:
                filled[g] = Outcome.NOT_EVALUATED
            samples[-1] = InteriorSample(
                u=samples[-1].u,
                outcomes=filled,
                note=samples[-1].note,
                per_direction=samples[-1].per_direction,
            )
    return tuple(samples)


def replace_object(state: FieldState, obj: TypedObject) -> FieldState:
    new_state = state.copy()
    new_state.objects[obj.object_id] = obj
    return new_state


def drop_object(state: FieldState, object_id: str, *, reason: str) -> FieldState:
    new_state = state.copy()
    obj = new_state.objects[object_id]
    new_state.objects[object_id] = replace(
        obj,
        held=False,
        recoverable=False,
        notes=(obj.notes + f" | dropped: {reason}").strip(" |"),
    )
    new_state.epoch = state.epoch + 1
    return new_state
